"""Wave 2 (DB integrity) - care_continuum + national FK-dependency closure.

Revision ID: 20261119_0003
Revises: 20261119_0002

PROBLEM
-------
The 45 ``cc_*`` care-continuum ORM tables had ZERO migration coverage although a
1,016-line router and 1,084-line service operate on them at runtime.  Their 249
FKs target ``national_*`` tables, 17 of which are also absent from the migration
chain.  A partial (cc-only) migration would therefore be invalid on a fresh
install (dangling FK targets).

SCOPE / EVIDENCE (Wave 2 probes; see GOVERNANCE/EXECUTION_LEDGER.md)
-------------------------------------------------------------------
* Transitive FK closure from the SAME merged 17-base metadata surface registered
  in ``migrations/env.py`` (NR-011 fix): 360 merged tables; 63-table closure
  (45 CareContinuumBase + 18 NationalBase FK targets); ``sorted_tables`` resolves.
* The true missing set was then derived from ACTUAL database state: a fresh
  disposable PostgreSQL was upgraded to the prior head (``20261119_0002``) and
  inspected.  1 of the 18 FK targets (``national_facilities``) already exists via
  a variable-named ``create_table`` in ``20260813_0004`` -- so it is NOT recreated.
  True missing set = 62 tables (45 ``cc_*`` + 17 ``national_*``).
* DDL generated by Alembic autogenerate against an empty DB from exactly those 62
  table definitions (no hand-written column lists).  Core columns use generic
  SQLAlchemy types; the 24 shared native PG ENUM types are managed explicitly
  (idempotent CREATE/DROP TYPE, ``create_type=False`` on each column) so the
  downgrade -> re-upgrade cycle is deterministic.
* Disposable PostgreSQL 16 lifecycle test (unique throwaway DB, synthetic data):
  upgrade -> 62 tables; FK + UNIQUE constraints enforced; downgrade -> 0 tables;
  re-upgrade -> 62 tables.  All passed.

COMPATIBILITY / SECURITY / MIGRATION IMPACT
-------------------------------------------
* Additive only: creates 62 previously-unmigrated tables.  No existing table,
  column, constraint, permission or API contract is altered.  Idempotent guards
  skip cleanly when all target tables already exist.
* The 17 ``national_*`` tables are migrated SOLELY as FK dependencies of
  care_continuum; the remaining national-schema backlog is unchanged.
* No data migration, no fake stamp, no ``create_all()``, no operational DB.
* Fully reversible: ``downgrade`` drops exactly these 62 tables (and their
  indexes), in dependency-safe reverse order.

Owner directive GULA-AUTONOMOUS-MASTER-EXECUTION 2026-11-19, SS5 Wave 2 / SS8.
"""
