    # use_alter=True to break the mutual FK cycle with
    # national_referrals.encounter_id -> national_encounters.id. Alembic's
    # op.create_table() SILENTLY SKIPS use_alter=True FKs (they are only emitted
    # by AddConstraint during MetaData.create_all), so the inline constraint in
    # national_encounters above is NOT present in the migrated schema. Recreate
    # it explicitly now that both tables exist, restoring referential integrity.
    op.create_foreign_key(
        "fk_national_encounters_referral",
        "national_encounters",
        "national_referrals",
        ["referral_id"],
        ["id"],
        ondelete="SET NULL",
    )
